auto* DrawInterface{ExecuteContext.GetDrawInterface()};
if (DrawInterface != nullptr && bDrawDebug)
{
	DrawInterface->DrawLine(FTransform::Identity, TraceStart, TraceEnd, {0.0f, 0.25f, 1.0f}, 1.0f);

	if (Hit.bBlockingHit)
	{
		DrawInterface->DrawPoint(FTransform::Identity, Hit.ImpactPoint, 12.0f, {0.0f, 0.75f, 1.0f});
	}
}

const auto HitNormal{ExecuteContext.GetToWorldSpaceTransform().InverseTransformVector(Hit.ImpactNormal)};

if (!Hit.bBlockingHit || HitNormal.Z < FMath::Cos(FMath::DegreesToRadians(WalkableFloorAngle)))
{
	OffsetLocationZ = 0.0f;
	OffsetNormal = FVector::UpVector;
	return;
}

const auto HitLocation{ExecuteContext.ToVMSpace(Hit.ImpactPoint)};

// Calculate how much we need to offset the foot along the Z axis to get it perfectly aligned with the sloped surface.
// Without this, the foot will sink into the surface. This formula can be derived from the right triangle cosine formula
// cos(a) = adjacent / hypotenuse, where cos(a) is SlopeAngleCos and adjacent is FootHeight. HitLocation.Z already contains
// a correction for FootHeight, so we need to subtract the FootHeight at the end of the formula so it won't be applied twice.

const auto SlopeAngleCos{UE_REAL_TO_FLOAT(HitNormal.Z)};
const auto SlopeOffsetZ{SlopeAngleCos > UE_SMALL_NUMBER ? FootHeight / SlopeAngleCos - FootHeight : 0.0f};

OffsetLocationZ = UE_REAL_TO_FLOAT(HitLocation.Z + SlopeOffsetZ);
OffsetNormal = HitNormal;

/**
 * Returns the topology version of this hierarchy
 */
uint32 GetTopologyVersion() const { return TopologyVersion; }

/**
 * Returns the hash of this hierarchy used for cached element keys
 */
uint32 GetTopologyVersionHash() const
{
	const uint32 Hash = HashCombine(
		(uint32)reinterpret_cast<long long>(this),
		GetTypeHash(TopologyVersion));
	if(ElementKeyRedirector)
	{
		return HashCombine(Hash, ElementKeyRedirector->GetHash());
	}
	return Hash;
}

bool FCachedRigElement::UpdateCache(const URigHierarchy* InHierarchy)
{
	if(InHierarchy)
	{
		if(!IsValid() || InHierarchy->GetTopologyVersionHash() != ContainerVersion || Element != InHierarchy->Get(Index))
		{
			return UpdateCache(GetKey(), InHierarchy);
		}
		return IsValid();
	}
	return false;
}

bool FCachedRigElement::UpdateCache(const FRigElementKey& InKey, const URigHierarchy* InHierarchy)
{
	if(InHierarchy)
	{
		if(!IsValid() || !IsIdentical(InKey, InHierarchy) || Element != InHierarchy->Get(Index))
		{
			// have to create a copy since Reset below
			// potentially resets the InKey as well.
			const FRigElementKey KeyToResolve = InKey;

			// first try to resolve with the known index.
			// this happens a lot - where the topology version has
			// increased - but the known item is still valid
			if(InHierarchy->IsValidIndex(Index))
			{
				if(const FRigBaseElement* PreviousElement = InHierarchy->Get(Index))
				{
					if(PreviousElement->GetKey() == KeyToResolve)
					{
						Key = KeyToResolve;
						Element = PreviousElement;
						ContainerVersion = InHierarchy->GetTopologyVersionHash();
						return IsValid();
					}
				}
			}

			int32 Idx = InHierarchy->GetIndex(KeyToResolve);
			if(Idx != INDEX_NONE)
			{
				Key = KeyToResolve;
				Index = (uint16)Idx;
				Element = InHierarchy->Get(Index);
			}
			else
			{
				Invalidate();
				Key = KeyToResolve;
			}

			ContainerVersion = InHierarchy->GetTopologyVersionHash();
		}
		return IsValid();
	}
	return false;

}

/**
 * Converts a location from VM (global) space to world space
 */
FVector ToWorldSpace(const FVector& InLocation) const
{
	return ToWorldSpaceTransform.TransformPosition(InLocation);
}

/**
 * Converts a location from world space to VM (global) space
 */
FVector ToVMSpace(const FVector& InLocation) const
{
	return ToWorldSpaceTransform.InverseTransformPosition(InLocation);
}

